func (s *Site) getPagesInSection(q pageMapQueryPagesInSection) page.Pages {
	m := s.pageMap
	cacheKey := "gagesInSection/" + q.Path + "/" + q.KeyPart + "/" + strconv.FormatBool(q.Recursive) + "/" + strconv.FormatBool(q.IncludeSelf) + "/" + m.cfg.lang

	pages, err := m.cachePages.GetOrCreate(cacheKey, func(string) (page.Pages, error) {
		prefix := paths.AddTrailingSlash(q.Path)

		var pas page.Pages

		requestedInclude := q.Include
		if requestedInclude == nil {
			requestedInclude = pagePredicates.ShouldListLocal
		}
		include := func(p *pageState) bool {
			pm := p.m
			pagePath := pm.Path()
			pageKind := pm.Kind()
			if pm.bundled {
				return false
			}
			if pageKind == "" && pagePath == "" {
				return false
			}
			if q.Path != "" && pagePath != q.Path && !strings.HasPrefix(pagePath, prefix) {
				return false
			}
			return requestedInclude(p)
		}

		w := &doctree.NodeShiftTreeWalker[contentNodeI]{
			Tree:   m.treePages,
			Prefix: prefix,
			Handle: func(key string, n contentNodeI, match doctree.DimensionFlag) (bool, error) {
				if q.Recursive {
					if p, ok := n.(*pageState); ok && include(p) {
						pas = append(pas, p)
					}
					return false, nil
				}

				// We store both leafs and branches in the same tree, so for non-recursive walks,
				// we need to walk until the end, but can skip
				// any not belonging to child branches.
				if p, ok := n.(*pageState); ok && include(p) {
					pas = append(pas, p)
				}

				if n.isContentNodeBranch() {
					// Skip the branch's descendants. Note that we cannot rely on the
					// branch and its descendants being contiguous in the walk, as
					// e.g. "s1-foo" sorts before "s1/p1".
					w.SkipPrefix(key + "/")
				}

				return false, nil
			},
		}

		err := w.Walk(context.Background())

		if err == nil {
			if q.IncludeSelf {
				if n := m.treePages.Get(q.Path); n != nil {
					if p, ok := n.(*pageState); ok && include(p) {
						pas = append(pas, p)
					}
				}
			}
			page.SortByDefault(pas)
		}

		return pas, err
	})
	if err != nil {
		panic(err)
	}

	return pages
}

